const $=s=>document.querySelector(s);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2}).format(Number(v)||0);
const money=v=>`${n(v)} <small>تومان</small>`;
const date=v=>formatPersianDate(v);
const today=()=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Tehran'}).format(new Date());
const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',projects:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/><path d="M3 10h18"/>',reports:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h4"/>',team:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v3"/>',finance:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18M15 14h6"/>',inventory:'<path d="m12 3 9 5v9l-9 5-9-5V8Z"/><path d="m3 8 9 5 9-5M12 13v9M7 5.8l9 5"/>',messages:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a9 9 0 1 1 17-5Z"/><path d="M7 10h10M7 14h6"/>',support:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 11H3v7h4v-7ZM20 11h1v7h-4v-7ZM19 18a4 4 0 0 1-4 4h-3"/>',assistant:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4M18 4h4"/>',analytics:'<path d="M4 3v18h17M8 17v-5M13 17V8M18 17V4"/>',settings:'<path d="m10 3-1 3-3 1-3 3 2 2-1 4 3 1 2 4h4l1-3 4-1 2-3-2-3 1-4-4-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M19 12H5m6-6-6 6 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4ZM10 20h4"/>',check:'<path d="m5 12 4 4L20 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',location:'<path d="M19 10c0 6-7 12-7 12S5 16 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',logout:'<path d="M9 4H4v16h5M14 8l5 4-5 4M8 12h11"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',send:'<path d="m21 3-7 18-4-8-8-4ZM10 13 21 3"/>',chevron:'<path d="m9 5 7 7-7 7"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>'};
const alias={users:'team',user:'team',file:'reports',folder:'projects',box:'inventory',wallet:'finance',sparkles:'assistant',ticket:'support',activity:'analytics',alert:'bell'};
const icon=name=>`<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[alias[name]||name]||paths.projects}</svg>`;
const labels={active:['در حال اجرا','green'],attention:['نیازمند پیگیری','gold'],completed:['تکمیل‌شده','blue'],submitted:['در انتظار تأیید','gold'],approved:['تأییدشده','green'],changes_requested:['نیازمند اصلاح','gold'],rejected:['ردشده','red'],open:['باز','gold'],in_progress:['در حال بررسی','blue'],resolved:['حل‌شده','green'],issued:['در انتظار پرداخت','gold'],paid:['پرداخت‌شده','green']};
const badge=s=>`<span class="badge ${(labels[s]||['','gray'])[1]}"><i></i>${e((labels[s]||[s])[0])}</span>`;
let state,session,query='',filter='all',tab='overview',messageProject,closeActiveModal;
const manager=()=>state.user.role==='manager',customer=()=>state.user.role==='customer';
const projectName=id=>projectLabel(state.projects.find(p=>p.id===id));
const personName=id=>state.users.find(p=>p.id===id)?.name||'عضو پروژه';
const go=hash=>{if(location.hash.slice(1)===hash)render();else location.hash=hash;};
const cover=p=>`./assets/photos/${({event:'arios-event',electric:'arios-smart-home',media:'arios-media'})[p.cover]||(/CCTV|نظارت|شبکه/i.test(p.type)?'arios-network':'arios-hero')}.webp`;
const avatar=u=>`<span class="avatar" title="${e(u?.name)}">${e((u?.name||'آ').split(' ').slice(0,2).map(s=>s[0]).join(''))}</span>`;
const progress=v=>`<div class="progress" role="progressbar" aria-label="درصد پیشرفت" aria-valuenow="${Number(v)||0}" aria-valuemin="0" aria-valuemax="100"><span class="progress-value" style="width:${Math.max(0,Math.min(100,Number(v)||0))}%"></span></div>`;
const btn=(text,action,cls='primary',ic='plus')=>`<button class="button ${cls}" data-action="${e(action)}">${icon(ic)}${text}</button>`;
const stat=(label,value,foot,ic)=>`<section class="card stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></section>`;
const total=(items=state.invoices)=>({issued:items.reduce((s,i)=>s+i.amount,0),paid:items.reduce((s,i)=>s+i.paid,0),due:items.reduce((s,i)=>s+i.amount-i.paid,0)});
const head=(title,subtitle,actions='')=>`<div class="page-head"><div><div class="eyebrow">ARIOS / ${customer()?'پرتال مشتری':'فضای کاری'}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const empty=(text='موردی برای نمایش وجود ندارد.')=>`<div class="empty">${icon('projects')}<p>${text}</p></div>`;
function projectCard(p){return `<article class="card project-card"><a class="project-cover" href="#project/${e(p.id)}"><img src="${cover(p)}" alt="تصویر مفهومی ${e(p.type)}" loading="lazy">${badge(p.status)}<span class="cover-code"><bdi dir="ltr">${e(p.projectCode||'کد ثبت نشده')}</bdi></span></a><div class="project-body"><div class="project-meta">${e(p.type)} · ${e(p.location)}</div><p class="project-lead-line">مسئول پروژه: ${e(state.users.find(user=>user.id===p.projectManagerId)?.name||'تعیین نشده')}</p><a class="project-card-title" href="#project/${e(p.id)}">${e(p.name)}${icon('arrow')}</a><div class="row between"><span class="muted">پیشرفت پروژه</span><strong>${n(p.progress)}٪</strong></div>${progress(p.progress)}<div class="project-foot"><div class="avatar-group">${p.memberIds.map(id=>avatar(state.users.find(u=>u.id===id))).join('')}</div><span>${icon('calendar')}${date(p.endDate)}</span></div></div></article>`;}
function dashboard(){
 if(customer())return customerDashboard();
 const workers=state.users.filter(u=>u.role==='worker'&&!u.deletedAt).length,pending=state.reports.filter(r=>r.status==='submitted').length,active=state.projects.filter(p=>p.status!=='completed').length,month=manager()?financialSeries(state,today()).at(-1):null;
 const metrics=manager()?stat('پروژه‌های در جریان',n(active),'در '+n(new Set(state.projects.map(p=>p.type)).size)+' حوزهٔ فعالیت','projects')+stat('اعضای تیم',n(workers),'یک تیم، برای نتیجه‌ای بهتر','team')+stat('دریافت وجه این ماه',money(month.received),e(month.label)+' · رسیدهای ثبت‌شده','finance')+stat('هزینهٔ ثبت‌شده این ماه',money(month.cost),'تجهیزات و کارکرد تأییدشده · '+n(pending)+' گزارش منتظر بررسی','reports'):stat('پروژه‌های من',n(active),'پروژه‌های تخصیص‌یافته','projects')+stat('گزارش‌های من',n(state.reports.length),'سوابق فعالیت شما','reports')+stat('ساعت تأییدشده',n(state.reports.filter(r=>r.status==='approved').reduce((s,r)=>s+r.minutes,0)/60),'پس از کسر استراحت','clock')+stat('تیکت‌های باز',n(state.tickets.filter(t=>t.status!=='resolved').length),'پیگیری مسائل پروژه','support');
 const counts=['active','attention','completed'].map(s=>state.projects.filter(p=>p.status===s).length),all=state.projects.length||1,a=counts[0]/all*100,b=(counts[0]+counts[1])/all*100;
 const days=Array.from({length:7},(_,i)=>{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-6+i);const iso=d.toISOString().slice(0,10);return {name:new Intl.DateTimeFormat('fa-IR',{weekday:'short'}).format(d),approved:state.reports.filter(r=>r.date===iso&&r.status==='approved').reduce((s,r)=>s+r.minutes/60,0),pending:state.reports.filter(r=>r.date===iso&&r.status==='submitted').reduce((s,r)=>s+r.minutes/60,0)};});const max=Math.max(8,...days.map(d=>d.approved+d.pending));
 const onboarding=manager()&&!state.projects.length?'<section class="card"><h2>راه‌اندازی فضای کار آریوس</h2><p class="muted">ابتدا نیروها را ثبت کنید، یک پروژه بسازید و سپس اتصال ویس را فعال کنید.</p><div class="actions"><a class="button secondary" href="#team">۱. اعضای تیم</a><a class="button secondary" href="#projects">۲. پروژه‌ها</a><a class="button primary" href="#voice">۳. اتصال تلگرام و ویس</a></div></section>':'';
 return head(manager()?'داشبورد مدیریتی':'فضای کار من',`${date(today())} · نمای یکپارچهٔ فعالیت‌های آریوس`,(reportProjects(state).length?btn('ثبت گزارش کار','report','secondary','reports'):'')+(manager()?btn('پروژهٔ جدید','project'):''))+onboarding+(dossierReviewCount(state)?`<div class="notice dossier-dashboard-notice">${n(dossierReviewCount(state))} گزارش تفصیلی در انتظار تأیید شماست. <a class="text-link" href="#reports">بررسی پرونده‌ها ${icon('arrow')}</a></div>`:'')+`${renderWorkspaceNextActions(state,workflowContext())}<div class="grid metrics">${metrics}</div><div class="dashboard-chart-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">کارکرد ثبت‌شدهٔ هفته</h2><p class="muted">ساعت فعالیت پس از کسر استراحت</p></div><div class="legend"><span><i style="background:var(--teal)"></i>تأییدشده</span><span><i style="background:var(--gold-light)"></i>در انتظار</span></div></div><div class="bar-chart">${days.map(d=>`<div class="bar-group" title="${e(d.name)}: ${n(d.approved)} ساعت تأییدشده و ${n(d.pending)} ساعت منتظر"><div class="bars"><span class="chart-bar" style="height:${d.approved/max*145}px;background:var(--teal)"></span><span class="chart-bar" style="height:${d.pending/max*145}px;background:var(--gold-light)"></span></div><span>${e(d.name)}</span></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2 class="card-title">نبض پروژه‌ها</h2><a class="text-link" href="#projects">همهٔ پروژه‌ها ${icon('arrow')}</a></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(var(--teal) 0% ${a}%,var(--gold) ${a}% ${b}%,#9eb4cd ${b}% 100%)"><div class="donut-hole"><strong>${n(state.projects.length)}</strong><span>پروژه</span></div></div><div class="legend vertical">${['active','attention','completed'].map((s,i)=>`<div class="legend-item"><span><i style="background:${['var(--teal)','var(--gold)','#9eb4cd'][i]}"></i>${labels[s][0]}</span><b>${n(counts[i])}</b></div>`).join('')}</div></div></section></div><div class="dashboard-bottom-grid"><section class="card"><div class="card-head"><h2 class="card-title">پروژه‌های در جریان</h2><a class="text-link" href="#projects">مشاهدهٔ همه ${icon('arrow')}</a></div><div class="table-wrap"><table><thead><tr><th>پروژه</th><th>پیشرفت</th><th>تحویل برنامه‌ریزی‌شده</th><th>وضعیت</th></tr></thead><tbody>${state.projects.map(p=>`<tr><td><a class="project-cell" href="#project/${e(p.id)}"><img src="${cover(p)}" alt=""><div><strong>${e(p.name)}</strong><small>${e(p.type)}</small></div></a></td><td><div class="progress-cell">${progress(p.progress)}<span>${n(p.progress)}٪</span></div></td><td>${date(p.endDate)}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><h2 class="card-title">آخرین گزارش‌های تیم</h2><a class="text-link" href="#reports">${icon('arrow')}</a></div><div class="activity-list">${state.reports.slice(0,4).map(r=>`<a class="activity-item" href="#reports">${avatar(state.users.find(u=>u.id===r.workerId))}<div><strong>${e(personName(r.workerId))}</strong><p>${e(projectName(r.projectId))}</p><small>${e((r.output||r.description).slice(0,80))}</small></div>${badge(r.status)}</a>`).join('')||empty()}</div><a class="assistant-mini" href="#assistant">${icon('assistant')}<div><strong>دستیار آریوس</strong><span>اطلاعات پروژه، نزدیک‌تر از همیشه</span></div>${icon('arrow')}</a></section></div>`;
}
function customerDashboard(){const t=total(),p=state.projects[0];return head(`سلام ${e(state.user.name)}، خوش آمدید`,'پروژه‌های شما، با جزئیاتی روشن و قابل پیگیری.',`<a class="button secondary" href="#support">${icon('support')}ارتباط با پشتیبانی</a>`)+`<section class="customer-hero"><div><div class="eyebrow">پرتال اختصاصی مشتری</div><h2>از روند کارتان باخبر بمانید</h2><p>پیشرفت، تجهیزات مصرفی، صورت‌حساب‌ها و گفت‌وگو با تیم آریوس؛ همه در یک جا.</p><a class="button primary" href="#${p?'project/'+e(p.id):'projects'}">مشاهدهٔ پروژه ${icon('arrow')}</a></div>${p?`<img src="${cover(p)}" alt="تصویر مفهومی پروژه">`:''}</section><div class="grid metrics">${stat('پروژه‌های من',n(state.projects.length),'اختصاص‌یافته به حساب شما','projects')+stat('صورت‌حساب صادرشده',money(t.issued),'مجموع صورت‌حساب‌های پروژه','reports')+stat('پرداخت ثبت‌شده',money(t.paid),'بر اساس دریافت‌های ثبت‌شده','finance')+stat('ماندهٔ قابل پرداخت',money(t.due),'ماندهٔ صورت‌حساب‌ها','clock')}</div><div class="page-head compact"><h2>پروژه‌های شما</h2><a class="text-link" href="#projects">مشاهدهٔ همه ${icon('arrow')}</a></div><div class="project-grid">${state.projects.map(projectCard).join('')||empty('هنوز پروژه‌ای به حساب شما تخصیص داده نشده است.')}</div><div class="grid two" style="margin-top:24px"><section class="card"><div class="card-head"><h2 class="card-title">پیام‌های تیم آریوس</h2><a class="text-link" href="#messages">همهٔ پیام‌ها ${icon('arrow')}</a></div>${state.messages.filter(m=>m.authorId!==state.user.id).slice(-3).reverse().map(m=>`<div class="activity-item">${avatar(state.users.find(u=>u.id===m.authorId))}<div><strong>${e(projectName(m.projectId))}</strong><p>${e(m.text)}</p><small>${date(m.createdAt)}</small></div></div>`).join('')||empty('پیام تازه‌ای ندارید.')}</section><section class="card"><div class="card-head"><h2 class="card-title">درخواست‌های پشتیبانی</h2><a class="text-link" href="#support">پیگیری ${icon('arrow')}</a></div>${state.tickets.map(t=>`<a class="ticket-row" href="#support"><span class="stat-icon">${icon('support')}</span><div class="ticket-summary"><strong>${e(t.subject)}</strong><small>${e(projectName(t.projectId))} · ${date(t.createdAt)}</small></div>${badge(t.status)}</a>`).join('')||empty('درخواست بازی ندارید.')}</section></div>`;}
function projects(){const items=state.projects.filter(p=>(filter==='all'||p.status===filter)&&projectMatchesQuery(p,query,state.users));return head(customer()?'پروژه‌های من':'مدیریت پروژه‌ها','هر پروژه، یک پروندهٔ کامل؛ از برنامه‌ریزی تا تحویل.',manager()?btn('پروژهٔ جدید','project'):'')+`<section class="card project-toolbar"><div class="tabs filter-tabs">${[['all','همهٔ پروژه‌ها'],['active','در حال اجرا'],['attention','نیازمند پیگیری'],['completed','تکمیل‌شده']].map(([v,l])=>`<button class="tab ${filter===v?'active':''}" data-filter="${v}">${l}<span>${n(state.projects.filter(p=>v==='all'||p.status===v).length)}</span></button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="project-search" value="${e(query)}" placeholder="کد، نام پروژه یا مسئول پروژه…" aria-label="جست‌وجوی کد، نام یا مسئول پروژه"></label></section><div class="project-grid">${items.map(projectCard).join('')||empty('پروژه‌ای با این مشخصات پیدا نشد.')}</div>`;}
function projectDetail(id){
 const p=state.projects.find(p=>p.id===id);if(!p)return head('پروژه در دسترس نیست','از فهرست پروژه‌های مجاز خود انتخاب کنید.')+empty();
 const {reviewOnly,canRecord,tabs}=projectViewPermissions(p,state.user);
 if(!tabs[tab])tab='overview';const materials=state.materials.filter(m=>m.projectId===id),invoices=state.invoices.filter(i=>i.projectId===id),t=total(invoices);let content='';
 if(tab==='overview')content=`<div class="project-detail-grid"><section class="card"><div class="card-head"><h2 class="card-title">مسیر اجرای پروژه</h2><span class="muted">${n((p.phases||[]).length)} مرحله</span></div><div class="timeline">${(p.phases||[]).map((ph,i)=>`<div class="timeline-item"><span class="phase-index ${ph.progress===100?'done':''}">${ph.progress===100?icon('check'):n(i+1)}</span><div><div class="row between"><strong>${e(ph.name)}</strong><b>${n(ph.progress)}٪</b></div>${progress(ph.progress)}<small class="muted">${ph.progress===100?'انجام‌شده':ph.progress===0?'در انتظار شروع':'در حال انجام'}</small></div></div>`).join('')}</div><div class="notice"><strong>پیام مسئول پروژه</strong><p>${e(p.clientNote||'هنوز یادداشتی منتشر نشده است.')}</p></div></section><div class="stack"><section class="card"><div class="card-head"><h2 class="card-title">شناسنامهٔ پروژه</h2></div><div class="info-row"><span>نوع فعالیت</span><strong>${e(p.type)}</strong></div><div class="info-row"><span>آغاز پروژه</span><strong>${date(p.startDate)}</strong></div><div class="info-row"><span>تحویل برنامه‌ریزی‌شده</span><strong>${date(p.endDate)}</strong></div>${p.contractAmount!==undefined?`<div class="info-row"><span>ارزش قرارداد</span><strong>${money(p.contractAmount)}</strong></div>`:''}<div class="info-row"><span>محل اجرا</span><strong>${e(p.location)}</strong></div><p class="muted">${e(p.description)}</p></section><section class="card"><div class="card-head"><h2 class="card-title">تیم پروژه</h2></div>${p.memberIds.map(id=>state.users.find(u=>u.id===id)).filter(Boolean).map(u=>`<div class="activity-item">${avatar(u)}<div><strong>${e(u.name)}</strong><p>${e(u.skill||u.department||'عضو تیم')}</p></div></div>`).join('')}${!reviewOnly?`<button class="button secondary full" data-tab="messages">${icon('messages')}ارسال پیام به تیم</button>`:''}</section></div></div>`;
 if(tab==='materials'&&customer())content=`<section class="card"><div class="card-head"><div><h2 class="card-title">اقلام مصرف‌شده در پروژه</h2><p class="muted">${customer()?'اقلام منتشرشده برای شما؛ مبلغ‌ها به تومان است.':'ثبت مصرف واقعی، مستقل از خرید کالا.'}</p></div>${manager()?btn('ثبت مصرف','material'):''}</div><div class="table-wrap"><table><thead><tr><th>نام کالا</th><th>مقدار</th><th>واحد</th><th>تاریخ</th>${manager()||customer()?'<th>قیمت واحد</th><th>مبلغ</th>':''}${manager()?'<th>نمایش مشتری</th>':''}</tr></thead><tbody>${materials.map(m=>`<tr><td><strong>${e(m.name)}</strong></td><td>${n(m.quantity)}</td><td>${e(m.unit)}</td><td>${date(m.date)}</td>${manager()||customer()?`<td>${money(m.unitPrice)}</td><td>${money(Math.round(m.quantity*m.unitPrice))}</td>`:''}${manager()?`<td><span class="badge ${m.clientVisible?'green':'gray'}">${m.clientVisible?'منتشرشده':'داخلی'}</span></td>`:''}</tr>`).join('')}</tbody></table></div>${!materials.length?empty('هنوز مصرفی ثبت نشده است.'):''}${manager()||customer()?`<div class="invoice-total"><span>جمع اقلام ${customer()?'منتشرشده':''}</span><strong>${money(materials.reduce((s,m)=>s+Math.round(m.quantity*m.unitPrice),0))}</strong></div>`:''}</section>`;
 if(tab==='materials'&&!customer())content=renderInventoryWorkspace(state,{...workflowContext(),inventoryProjectId:id});
 if(tab==='reports')content=`<section class="card"><div class="card-head"><h2 class="card-title">گزارش‌های پروژه</h2>${canRecord?btn('گزارش جدید','report'):''}</div>${state.reports.filter(r=>r.projectId===id).map(r=>`<div class="report-summary"><div class="row between"><strong>${e(personName(r.workerId))} · ${date(r.date)}</strong>${badge(r.status)}</div><p>${e(r.description)}</p>${renderReportAttachments(r,workflowContext())}<div class="row between"><small>${e(r.start)} تا ${e(r.end)} · ${n(r.minutes/60)} ساعت خالص</small><a class="text-link" href="#reports">بررسی گزارش‌ها ${icon('arrow')}</a></div></div>`).join('')||empty('گزارشی ثبت نشده است.')}</section>`;
 if(tab==='finance')content=`<div class="grid three">${stat('صورت‌حساب صادرشده',money(t.issued),'صورت‌حساب‌های این پروژه','reports')+stat('پرداخت ثبت‌شده',money(t.paid),'دریافت‌های ثبت‌شده','finance')+stat('ماندهٔ صورت‌حساب',money(t.due),'مستقل از مبلغ کل قرارداد','clock')}</div><section class="card" style="margin-top:24px"><div class="card-head"><h2 class="card-title">صورت‌حساب‌های پروژه</h2>${manager()?btn('صورت‌حساب جدید','invoice'):''}</div>${invoices.map(i=>`<div class="invoice-row"><span class="stat-icon">${icon('reports')}</span><div class="invoice-info"><strong>${e(i.title)}</strong><p>سررسید ${date(i.dueDate)}</p></div><div class="money"><strong>${money(i.amount-i.paid)}</strong><small>مانده</small></div>${badge(i.status)}</div>`).join('')||empty('صورت‌حسابی صادر نشده است.')}<a class="button secondary" href="#finance">${icon('finance')}${customer()?'مشاهدهٔ جزئیات و هماهنگی پرداخت':'مدیریت دریافت‌ها'}</a></section>`;
 if(['tasks','team','files'].includes(tab))content=renderProjectWorkspace(state,p,tab,workflowContext());
 if(tab==='dossier')content=renderProjectDossier(state,p,workflowContext());
 if(tab==='overview'&&!customer())content+=renderProjectReviewChain(state,p,workflowContext());
 if(tab==='messages')content=messages(id);
 if(tab==='support')content=`<section class="card"><div class="card-head"><h2 class="card-title">پشتیبانی ${e(p.name)}</h2><a class="button primary" href="#support">${icon('support')}مرکز پشتیبانی</a></div>${state.tickets.filter(t=>t.projectId===id).map(t=>`<a class="ticket-row" href="#support"><div class="ticket-summary"><strong>${e(t.subject)}</strong><p>${e(t.description)}</p></div>${badge(t.status)}</a>`).join('')||empty('درخواستی برای این پروژه ثبت نشده است.')}<a class="assistant-mini" href="#assistant">${icon('assistant')}راهنمای پروژه و ثبت درخواست پشتیبانی ${icon('arrow')}</a></section>`;
 return `<a class="text-link back-link" href="#${state.user.role==='accountant'?'reports':'projects'}">${icon('chevron')}${state.user.role==='accountant'?'بازگشت به گزارش‌ها':'بازگشت به پروژه‌ها'}</a><section class="project-banner"><img src="${cover(p)}" alt="تصویر مفهومی پروژه"><div class="project-banner-shade"></div><div class="project-banner-copy"><span class="eyebrow"><bdi dir="ltr">${e(p.projectCode||'کد ثبت نشده')}</bdi> · ${e(p.type)}</span><h1>${e(p.name)}</h1><p>${icon('location')}${e(p.location)}</p><div class="actions">${badge(p.status)}${manager()?btn('به‌روزرسانی پروژه','update-project','secondary','settings'):''}</div></div><div class="project-banner-progress"><span>پیشرفت ثبت‌شدهٔ مدیر</span><strong>${n(p.progress)}<small>٪</small></strong>${progress(p.progress)}</div></section>${renderProjectIdentity(state,p,workflowContext())}<div class="tabs detail-tabs">${Object.entries(tabs).map(([v,l])=>`<button class="tab ${tab===v?'active':''}" data-tab="${v}">${l}</button>`).join('')}</div>${content}`;
}
function messages(pid){if(!state.projects.length)return head('گفت‌وگوهای پروژه','پیام‌های هر پروژه در فضای اختصاصی همان پروژه ثبت می‌شوند')+`<section class="card empty-state"><h2>هنوز پروژه‌ای در دسترس شما نیست</h2><p>${manager()?'ابتدا پروژه بسازید و اعضای آن را مشخص کنید':'مدیر باید پروژه را به حساب شما اختصاص دهد'}</p><div class="actions"><a class="button primary" href="#${manager()?'projects':'assistant'}">${manager()?'مدیریت پروژه‌ها':'گفت‌وگوی عمومی با آریوس'}</a></div></section>`;const selected=state.projects.find(p=>p.id===(pid||messageProject))?.id||state.projects[0]?.id;messageProject=selected;const list=state.messages.filter(m=>m.projectId===selected);return `${pid?'':head('گفت‌وگوهای پروژه','ارتباط روشن، در همان جایی که کار پیش می‌رود.')}<section class="card"><div class="card-head"><div><h2 class="card-title">${e(projectName(selected))}</h2><p class="muted">${customer()?'گفت‌وگو با تیم مسئول پروژه':'پیام‌های مشتری و یادداشت‌های تیم'}</p></div>${pid?'':`<select id="message-project" aria-label="انتخاب پروژه">${state.projects.map(p=>`<option value="${e(p.id)}" ${p.id===selected?'selected':''}>${e(p.name)}</option>`).join('')}</select>`}</div><div class="chat-thread" id="messages-thread">${list.map(m=>`<article class="chat-message ${m.authorId===state.user.id?'mine':''} ${m.internal?'internal':''}"><div class="row between"><strong>${e(personName(m.authorId))}</strong>${m.internal?'<span class="badge gold">یادداشت داخلی</span>':''}</div><p>${e(m.text).replace(/\n/g,'<br>')}</p><small>${date(m.createdAt)}</small></article>`).join('')||empty('گفت‌وگو را شروع کنید.')}</div><form id="message-form" class="chat-composer"><label class="sr-only" for="message-text">متن پیام</label><textarea id="message-text" name="text" rows="2" placeholder="پیامتان را بنویسید…" required maxlength="6000"></textarea><div class="row between">${customer()?'':`<label class="checkbox-label"><input type="checkbox" name="internal">یادداشت داخلی تیم</label>`}<button class="button primary" type="submit" ${!selected?'disabled':''}>${icon('send')}ارسال پیام</button></div></form></section>`;}
function sidebar(page){const {main,links}=portalNavigation(state.user.role);return `<aside class="sidebar" id="sidebar"><a class="brand" href="${session.authMode==='supabase'?'/':'#dashboard'}"><img class="brand-logo" src="/assets/brand/arios-logo-navy-gold-v2.webp" width="112" height="94" alt="لوگوی آریوس"><small class="brand-caption">فضای کار یکپارچهٔ آریوس</small></a><div class="workspace-label"><span class="workspace-icon"><img src="/assets/brand/arios-mark-navy-gold-v2.webp" width="24" height="24" alt=""></span><div><strong>گروه آریوس</strong><small>${customer()?'پرتال مشتریان':'فضای کار سازمانی'}</small></div><span class="status-dot"></span></div><nav aria-label="منوی اصلی"><div class="nav-group">${customer()?'پروژه و حساب من':'مدیریت و اجرا'}</div>${main.map(([v,l,ic])=>`<a class="nav-link ${page===v||(page==='project'&&v===(state.user.role==='accountant'?'reports':'projects'))?'active':''}" href="#${v}"><span class="nav-icon">${icon(ic)}</span>${l}${v==='reports'&&(dossierReviewCount(state)+(manager()?state.reports.filter(r=>r.status==='submitted').length:0))?`<span class="nav-count">${n(dossierReviewCount(state)+(manager()?state.reports.filter(r=>r.status==='submitted').length:0))}</span>`:''}</a>`).join('')}<div class="nav-group">همراه شما</div>${links.map(([v,l,ic])=>`<a class="nav-link ${page===v?'active':''}" href="#${v}"><span class="nav-icon">${icon(ic)}</span>${l}${v==='assistant'?'<span class="ai-tag">AI</span>':''}</a>`).join('')}${manager()?`<div class="nav-group">سازمان</div><a class="nav-link ${page==='analytics'?'active':''}" href="#analytics">${icon('analytics')}گزارش‌ها و تحلیل</a>` : ''}<a class="nav-link ${page==='settings'?'active':''}" href="#settings">${icon('settings')}${manager()?'تنظیمات و دسترسی‌ها':'اطلاعات حساب'}</a>${session.authMode==='supabase'?`<div class="nav-group">گروه آریوس</div><a class="nav-link" href="/">${icon('arrow')}معرفی و فعالیت‌ها</a>`:''}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('shield')}<span>${session.demo?'محیط نمونهٔ مستقل':'دسترسی بر اساس نقش و پروژه'}</span></div><div class="sidebar-user">${avatar(state.user)}<div><strong>${e(state.user.name)}</strong><small>${state.user.managementTitle||roleLabels[state.user.role]||'حساب آریوس'}</small></div><button class="icon-btn" data-action="logout" aria-label="خروج از حساب">${icon('logout')}</button></div></div></aside>`;}
function workflowContext(){return {userId:state?.user?.id,managementRoles:state?.managementRoles,e,n,money,date,today,icon,badge,head,empty,projectName,personName,go,mutate,modal,toast,api,refresh,openProject,openProjectUpdate,openReport,openInvoice,openMaterial,capabilities:session.capabilities,authMode:session.authMode,demo:session.demo};}
function render(){stopVoice();setDossierViewer(state?.user);if(!state)return;if(closeActiveModal)closeActiveModal();let [page='dashboard',id,requestedTab]=(location.hash.slice(1)||landingPage(state.user.role)).split('/');if(page==='dashboard'&&landingPage(state.user.role)!=='dashboard'){go(landingPage(state.user.role));return;}if(page==='project')tab=requestedTab||'overview';const ctx={...workflowContext(),inventoryView:page==='inventory'?id:''};let content;
 if(!allowedPortalPage(page,state.user.role))content=head('دسترسی این بخش فعال نیست','از منوی حساب خود استفاده کنید');else if(page==='management')content=renderAdminWorkspace(state,ctx,id,requestedTab);else if(page==='inventory')content=renderInventoryWorkspace(state,ctx);else if(page==='dashboard')content=dashboard();else if(page==='projects')content=projects();else if(page==='project')content=projectDetail(id);else if(page==='messages')content=messages();else if(page==='voice')content=renderVoice(state,ctx);else if(page==='leads')content=renderLeads(state,ctx);else if(['customers','calendar','documents'].includes(page))content=renderWorkspaceHub(page,state,ctx);else content=renderOperations(page,state,ctx);if(content==null)content=head('صفحه پیدا نشد','از منوی کنار صفحه انتخاب کنید.')+empty();
 const titles={dashboard:customer()?'پنل مشتری':'داشبورد مدیریتی',projects:'پروژه‌ها',project:projectName(id),reports:'گزارش‌های کار',voice:'ویس و گزارش هوشمند',team:'نیروها',inventory:'تجهیزات و انبار',finance:'مالی و صورت‌حساب',messages:'گفت‌وگوها',support:'مرکز پشتیبانی',assistant:'دستیار آریوس',analytics:'گزارش‌ها و تحلیل',settings:'تنظیمات',notifications:'مرکز پیگیری',leads:'درخواست‌های مشاوره',customers:'فروش و مشتریان',calendar:'تقویم و زمان‌بندی',documents:'مدارک و فایل‌ها',management:'مدیریت اطلاعات'};
 $('#app').innerHTML=`<div class="shell">${sidebar(page)}<button class="mobile-scrim" data-action="close-menu" aria-label="بستن منو" tabindex="-1"></button><div class="workspace"><header class="topbar"><div class="topbar-title"><button class="icon-btn mobile-menu" data-action="menu" aria-label="بازکردن منو">${icon('menu')}</button><span class="breadcrumb">گروه آریوس <span>/</span> <strong>${e(titles[page]||'فضای کار')}</strong></span></div><div class="topbar-tools">${manager()?'<a class="button secondary management-global-link" href="#management">مدیریت اطلاعات</a>':''}<form id="global-search" class="searchbox" ${['warehouse','accountant'].includes(state.user.role)?'hidden':''}>${icon('search')}<input name="query" aria-label="جست‌وجوی پروژه‌ها" placeholder="جست‌وجو در پروژه‌ها…"><kbd>⌕</kbd></form>${session.demo?`<label class="demo-switch"><span>نمایش پنل</span><select id="demo-role" aria-label="تغییر نقش در محیط نمونه">${[['manager','مدیر'],['worker','نیروی اجرایی'],['customer','مشتری آفتاب'],['customer2','مشتری پارس']].map(([v,l])=>`<option value="${v}" ${v===state.user.id?'selected':''}>${l}</option>`).join('')}</select></label>`:''}<button class="icon-btn notification" ${['warehouse','accountant'].includes(state.user.role)?'hidden':''} data-action="notifications" aria-label="مرکز پیگیری${portalNotifications(state).length?'؛ '+n(portalNotifications(state).length)+' مورد':''}">${icon('bell')}${portalNotifications(state).length?'<i></i>':''}</button><button class="icon-btn profile-button" data-action="profile" aria-label="اطلاعات حساب من">${avatar(state.user)}</button></div></header>${session.demo?`<div class="demo-banner"><span><i></i>نسخهٔ آزمایشی · تمام نام‌ها و مبالغ نمونه‌اند${api.isStatic?' · تغییرات فقط در همین مرورگر ذخیره می‌شود.':''}</span>${api.isStatic?`<a href="./downloads/ARIOS_OS_source.zip" download class="demo-download">${icon('download')}دریافت سورس</a>`:''}</div>`:''}<main class="content" id="main-content">${content}<footer class="page-footer"><span>${session.authMode==='supabase'?'<a href="/" class="text-link"><b>ARIOS OS</b></a>':'<b>ARIOS OS</b>'} · هر پروژه، یک مسیر روشن.</span><span>${session.authMode==='supabase'?'<a href="/" class="text-link">معرفی و فعالیت‌های آریوس</a>':'ساخت مستقل آریوس · نسخهٔ ۰.۲'}</span></footer></main></div></div><div id="toast" role="status" aria-live="polite"></div><div id="modal-root"></div>`;
 installPersianDateInputs($('#main-content'));
 document.title=(titles[page]||'فضای کار')+' | ARIOS OS';wireCommon(page,id);wireOperations(page,state,ctx);if(page==='management'&&manager())wireAdminWorkspace(state,ctx,id);if(page==='project'&&allowedPortalPage(page,state.user.role)){const selectedProject=state.projects.find(project=>project.id===id);wireProjectWorkspace(state,selectedProject,tab,ctx);if(tab==='dossier'&&selectedProject)wireProjectDossier(state,selectedProject,ctx);}if(page==='leads'&&allowedPortalPage(page,state.user.role))wireLeads(state,ctx);if(['customers','calendar','documents'].includes(page)&&allowedPortalPage(page,state.user.role))wireWorkspaceHub(page,state,ctx);if(page==='voice'&&allowedPortalPage(page,state.user.role))wireVoice(state,ctx);if(page==='inventory'||(page==='project'&&tab==='materials'))wireInventoryWorkspace(state,{...ctx,...(page==='project'?{inventoryProjectId:id}:{})});
}
function wireCommon(page,id){document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',async()=>{const a=el.dataset.action;if(a==='project')openProject();if(a==='report')openReport(page==='project'?id:undefined);if(a==='invoice')openInvoice(page==='project'?id:undefined);if(a==='material')openMaterial(page==='project'?id:undefined);if(a==='update-project')openProjectUpdate(id);if(a==='menu')$('#sidebar').classList.toggle('is-open');if(a==='close-menu')$('#sidebar').classList.remove('is-open');if(a==='notifications')go('notifications');if(a==='profile')go('settings');if(a==='logout'){setDossierViewer(null);if(session.authMode==='supabase'){try{await api.logout();location.assign('/');}catch(err){toast(err.message);}return;}if(session.authMode==='chatgpt'){location.assign('/signout-with-chatgpt?return_to=%2F');return;}try{await api.logout();if(api.isStatic){await refresh();toast('برای بررسی پنل‌ها از انتخاب نقش استفاده کنید.');}else{session=await api.session();renderLogin();}}catch(err){toast(err.message);}}}));
 $('#demo-role')?.addEventListener('change',async ev=>{try{await api.demoLogin(ev.target.value);tab='overview';messageProject=null;query='';filter='all';location.hash='dashboard';await refresh();}catch(err){toast(err.message);}});
 $('#global-search')?.addEventListener('submit',ev=>{ev.preventDefault();query=String(new FormData(ev.currentTarget).get('query')||'').trim();go('projects');});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render();});
 let timer;$('#project-search')?.addEventListener('input',ev=>{query=ev.target.value;clearTimeout(timer);timer=setTimeout(()=>{const p=ev.target.selectionStart;render();$('#project-search')?.focus();$('#project-search')?.setSelectionRange(p,p);},180);});
 document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{if(page==='project')go('project/'+id+'/'+el.dataset.tab);else{tab=el.dataset.tab;render();}});
 $('#message-project')?.addEventListener('change',ev=>{messageProject=ev.target.value;render();});
 $('#message-form')?.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget,d=new FormData(f),b=f.querySelector('button');b.disabled=true;try{await mutate('message.send',{projectId:page==='project'?id:messageProject,text:d.get('text'),internal:d.has('internal')});}catch(err){toast(err.message);b.disabled=false;}});const thread=$('#messages-thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
let toastTimer;
function toast(text){const el=$('#toast');if(!el)return;clearTimeout(toastTimer);el.className='toast visible';el.textContent=String(text);toastTimer=setTimeout(()=>el.className='toast',5000);}
function modal({title,body,onSubmit,submitLabel='ثبت و ذخیره'}){if(closeActiveModal)closeActiveModal();const root=$('#modal-root'),old=document.activeElement;root.innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn" id="modal-close" type="button" aria-label="بستن">${icon('close')}</button></div><form id="modal-form"><div class="modal-body">${body}<div id="modal-error" class="form-error" role="alert"></div></div><div class="modal-foot"><button type="submit" class="button primary">${icon('check')}${e(submitLabel)}</button><button type="button" class="button secondary" id="modal-cancel">انصراف</button></div></form></section></div>`;
 installPersianDateInputs(root);
 const close=()=>{closePersianDatePicker();root.innerHTML='';document.removeEventListener('keydown',keys);if(closeActiveModal===close)closeActiveModal=undefined;if(old?.isConnected)old.focus();};closeActiveModal=close;const keys=ev=>{if(ev.key==='Escape')close();if(ev.key==='Tab'){const list=[...root.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.type!=='hidden');const first=list[0],last=list.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}};document.addEventListener('keydown',keys);$('#modal-close').onclick=close;$('#modal-cancel').onclick=close;root.querySelector('.modal-overlay').onclick=ev=>{if(ev.target.classList.contains('modal-overlay'))close();};$('#modal-form').onsubmit=async ev=>{ev.preventDefault();const b=ev.currentTarget.querySelector('[type="submit"]'),err=$('#modal-error');b.disabled=true;err.textContent='';try{await onSubmit(new FormData(ev.currentTarget));close();}catch(error){if(err.isConnected)err.textContent=error.message;else toast(error.message);b.disabled=false;}};setTimeout(()=>(root.querySelector('input:not([type="hidden"]),select,textarea')||root.querySelector('#modal-close'))?.focus(),20);
}
async function mutate(action,payload){const r=await api.action(action,payload);state=r.state||await api.state();render();const warnings=Array.isArray(r.result?.warnings)?r.result.warnings.filter(value=>typeof value==='string'&&value.trim()):[];toast(['تغییرات ثبت شد',...warnings].join(' · '));return r.result;}
const field=(label,name,type='text',value='',extra='')=>`<label class="field"><span class="field-label">${label}</span><input type="${type}" name="${name}" value="${e(value)}" ${extra}></label>`;
const publicationFields=(project={})=>`<fieldset class="field full project-publication"><legend class="field-label">نمایش در سایت عمومی</legend><label class="checkbox-label"><input type="checkbox" name="publicVisible" ${project.publicVisible?'checked':''}>این پروژه در صفحهٔ عمومی آریوس نمایش داده شود</label><label class="field"><span class="field-label">عنوان عمومی پروژه</span><input name="publicTitle" maxlength="160" value="${e(project.publicTitle||'')}" placeholder="عنوانی مناسب نمایش به بازدیدکنندگان"></label><label class="field"><span class="field-label">خلاصهٔ عمومی</span><textarea name="publicSummary" rows="3" maxlength="1000" placeholder="توضیح کوتاه خدمات و نتیجهٔ اجرا، بدون اطلاعات خصوصی">${e(project.publicSummary||'')}</textarea></label><p class="muted">با فعال‌کردن نمایش، عنوان و خلاصهٔ عمومی منتشر می‌شوند. نام مشتری، محل اجرا و اطلاعات مالی منتشر نمی‌شوند.</p></fieldset>`;
const publicationPayload=form=>({publicVisible:form.has('publicVisible'),publicTitle:form.get('publicTitle'),publicSummary:form.get('publicSummary')});
function wirePublicationForm(){const form=$('#modal-form'),toggle=form?.querySelector('[name="publicVisible"]');if(!toggle)return;const refreshFields=()=>{for(const input of form.querySelectorAll('[name="publicTitle"],[name="publicSummary"]'))input.required=toggle.checked;};toggle.addEventListener('change',refreshFields);refreshFields();}
const projectSelect=(id,projects=state.projects)=>`<label class="field"><span class="field-label">پروژه</span><select name="projectId" required>${projects.map(p=>`<option value="${e(p.id)}" ${p.id===id?'selected':''}>${e(projectLabel(p))}</option>`).join('')}</select></label>`;
function prerequisite(title,description,links=[]){modal({title,submitLabel:'متوجه شدم',body:`<p>${e(description)}</p><div class="prerequisite-links">${links.map(([href,label])=>`<a class="button secondary" href="${e(href)}">${e(label)}</a>`).join('')}</div>`,onSubmit:async()=>{}});}
function openReport(id){return openReportComposer(state,workflowContext(),id);}
function openProject(){modal({title:'پروژهٔ جدید',body:`<div class="form-grid">${projectConfigurationFields(state,workflowContext())}${field('نام پروژه','name','text','','required maxlength="160"')}<label class="field"><span class="field-label">نوع فعالیت</span>${catalogSelect(state,'projectTypes',workflowContext(),{name:'type',required:true})}</label>${field('محل اجرا','location','text','','required')}<label class="field"><span class="field-label">مشتری</span><select name="customerId"><option value="">هنوز مشتری تخصیص داده نشده</option>${state.users.filter(u=>u.role==='customer'&&!u.deletedAt).map(u=>`<option value="${e(u.id)}">${e(u.name)}</option>`).join('')}</select></label>${field('ارزش قرارداد (تومان)','contractAmount','number',0,'min="0" required')}${field('بودجهٔ داخلی (تومان)','budget','number',0,'min="0" required')}${field('شروع پروژه','startDate','date',today(),'required')}${field('تحویل برنامه‌ریزی‌شده','endDate','date',today(),'required')}<fieldset class="field full"><legend class="field-label">اعضای تیم</legend>${state.users.filter(u=>u.role==='worker'&&!u.deletedAt).map(u=>`<label class="checkbox-label"><input type="checkbox" name="memberIds" value="${e(u.id)}">${e(u.name)}</label>`).join('')}</fieldset><label class="field full"><span class="field-label">شرح خدمات</span><textarea name="description" rows="3" maxlength="6000"></textarea></label>${publicationFields()}</div>`,onSubmit:f=>mutate('project.create',{name:f.get('name'),type:f.get('type'),location:f.get('location'),customerId:f.get('customerId'),memberIds:f.getAll('memberIds'),budget:Number(f.get('budget')),contractAmount:Number(f.get('contractAmount')),startDate:f.get('startDate'),endDate:f.get('endDate'),description:f.get('description'),...projectConfigurationPayload(f),...publicationPayload(f)})});wirePublicationForm();}
function openProjectUpdate(id){const p=state.projects.find(p=>p.id===id);modal({title:'به‌روزرسانی پروژه',body:`<div class="form-grid">${projectConfigurationFields(state,workflowContext(),p)}${field('پیشرفت کلی (%)','progress','number',p.progress,'min="0" max="100" required')}<label class="field"><span class="field-label">وضعیت</span><select name="status">${['active','attention','completed'].map(s=>`<option value="${s}" ${p.status===s?'selected':''}>${labels[s][0]}</option>`).join('')}</select></label><label class="field full"><span class="field-label">مشتری پروژه</span><select name="customerId"><option value="">بدون تخصیص مشتری</option>${state.users.filter(u=>u.role==='customer'&&!u.deletedAt).map(u=>`<option value="${e(u.id)}" ${p.customerId===u.id?'selected':''}>${e(u.name)}</option>`).join('')}</select></label><fieldset class="field full"><legend class="field-label">اعضای تیم اجرایی</legend>${state.users.filter(u=>u.role==='worker'&&!u.deletedAt).map(u=>`<label class="checkbox-label"><input type="checkbox" name="memberIds" value="${e(u.id)}" ${p.memberIds.includes(u.id)?'checked':''}>${e(u.name)}</label>`).join('')||'<p class="muted">ابتدا نیروی اجرایی تعریف کنید.</p>'}</fieldset><label class="field full"><span class="field-label">یادداشت قابل نمایش برای مشتری</span><textarea name="clientNote" rows="4" maxlength="4000">${e(p.clientNote)}</textarea></label>${publicationFields(p)}</div><p class="muted">تغییر اعضا و مشتری، دسترسی آن‌ها به پروژه را تغییر می‌دهد. سوابق قبلی حفظ می‌شوند.</p>`,onSubmit:f=>mutate('project.update',{id,progress:Number(f.get('progress')),status:f.get('status'),clientNote:f.get('clientNote'),customerId:f.get('customerId')||null,memberIds:f.getAll('memberIds'),...projectConfigurationPayload(f),...publicationPayload(f)})});wirePublicationForm();}
function openInvoice(id){if(!state.projects.length)return prerequisite('پیش‌نیاز صدور صورت‌حساب','ابتدا یک پروژه بسازید و مشتری آن را مشخص کنید',[['#projects','مدیریت پروژه‌ها']]);modal({title:'صدور صورت‌حساب',body:`<div class="form-grid">${projectSelect(id)}${field('عنوان صورت‌حساب','title','text','','required maxlength="200"')}${field('مبلغ (تومان)','amount','number','','required min="1"')}${field('سررسید','dueDate','date',today(),'required')}</div><div class="notice">صدور صورت‌حساب به معنی دریافت وجه نیست. این سند برای مشتری پروژه قابل مشاهده است.</div>`,onSubmit:f=>mutate('invoice.create',{projectId:f.get('projectId'),title:f.get('title'),amount:Number(f.get('amount')),dueDate:f.get('dueDate')})});}
function openMaterial(id){
 if(state.user.role==='worker'||state.user.role==='warehouse')return openInventoryConsumption(state,workflowContext(),id);
 if(!state.projects.length)return prerequisite('پیش‌نیاز ثبت مصرف','برای ثبت مصرف تجهیزات ابتدا پروژه را تعریف کنید',[['#projects','مدیریت پروژه‌ها']]);
 modal({title:'ثبت مصرف تجهیزات',body:`<div class="form-grid">${projectSelect(id)}${field('نام کالا','name','text','','required maxlength="200"')}${field('مقدار مصرف','quantity','number',1,'required min="0.001" step="0.001"')}${field('واحد','unit','text','عدد','required maxlength="50"')}${field('قیمت واحد (تومان)','unitPrice','number',0,'required min="0" step="1"')}${field('تاریخ مصرف','date','date',today(),'required')}<label class="field full"><span class="field-label">برداشت از انبار</span><select name="inventoryId"><option value="">ثبت قلم مستقل از انبار</option>${state.inventory.map(i=>`<option value="${e(i.id)}" ${Number(i.quantity)<=0?'disabled':''}>${e(i.name)} — ${n(i.quantity)} ${e(i.unit)}</option>`).join('')}</select><small data-material-stock>با انتخاب کالای انبار، نام، واحد و بهای آن به‌صورت خودکار تکمیل می‌شود</small></label><label class="checkbox-label field full"><input type="checkbox" name="clientVisible" checked>این قلم و قیمت آن برای مشتری منتشر شود</label></div>`,onSubmit:f=>mutate('material.create',{projectId:f.get('projectId'),name:f.get('name'),quantity:Number(f.get('quantity')),unit:f.get('unit'),unitPrice:Number(f.get('unitPrice')),date:f.get('date'),inventoryId:f.get('inventoryId')||undefined,clientVisible:f.has('clientVisible')})});
 const form=$('#modal-form'),selector=form?.querySelector('[name="inventoryId"]');
 selector?.addEventListener('change',()=>{
  const item=state.inventory.find(row=>row.id===selector.value),quantity=form.querySelector('[name="quantity"]');
  for(const name of ['name','unit'])form.querySelector(`[name="${name}"]`).readOnly=Boolean(item);
  const note=form.querySelector('[data-material-stock]');
  if(item){for(const name of ['name','unit','unitPrice'])form.querySelector(`[name="${name}"]`).value=item[name]??'';quantity.max=String(item.quantity);if(Number(quantity.value)>item.quantity)quantity.value=String(item.quantity);note.textContent=`موجودی قابل برداشت: ${n(item.quantity)} ${item.unit}`;}
  else{quantity.removeAttribute('max');note.textContent='این قلم مستقل ثبت می‌شود و از موجودی انبار کم نمی‌شود';}
 });
}
function renderLogin(){stopVoice();setDossierViewer(null);state=null;if(session?.authMode==='supabase'){const portal=session.portal==='client'||new URLSearchParams(location.search).get('portal')==='client'?'client':'team';location.replace('/login/'+portal);return;}if(session?.authMode==='chatgpt'){renderHostedLogin();return;}$('#app').innerHTML=`<main class="login-page"><section class="login-splash"><a class="brand" href="#"><img class="brand-logo" src="/assets/brand/arios-logo-navy-gold-v2.webp" width="150" height="126" alt="لوگوی آریوس"><small class="brand-caption">فضای کار یکپارچهٔ آریوس</small></a><div><div class="hero-kicker">به فضای کار آریوس خوش آمدید</div><h1>هر پروژه،<br>یک مسیر روشن</h1><p>مدیریت یکپارچهٔ پروژه، تیم و ارتباط با مشتری.</p></div><div class="login-splash-foot">ARIOS · OPERATIONS SYSTEM</div></section><section class="login-card"><div class="eyebrow">فضای کار یکپارچه</div><h2>ورود به آریوس</h2><p class="muted">با حساب اختصاصی خود وارد شوید.</p><form id="login-form"><label class="field"><span class="field-label">ایمیل</span><input name="email" type="email" autocomplete="username" dir="ltr" required></label><label class="field"><span class="field-label">رمز عبور</span><input name="password" type="password" autocomplete="current-password" required></label><div id="login-error" class="form-error" role="alert"></div><button class="button primary full" type="submit">ورود به فضای کار ${icon('arrow')}</button></form>${session?.demo?`<div class="login-demo"><p>یا نقش‌های نسخهٔ آزمایشی را بررسی کنید:</p><div class="role-options">${[['manager','مدیر','dashboard'],['worker','نیروی اجرایی','reports'],['customer','مشتری','projects']].map(([v,l,ic])=>`<button class="role-card" data-demo="${v}">${icon(ic)}<span>${l}</span>${icon('arrow')}</button>`).join('')}</div><small>تمام اطلاعات این محیط نمونه و فرضی است.</small></div>`:''}</section></main>`;$('#login-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),b=ev.currentTarget.querySelector('button');b.disabled=true;try{await api.login(f.get('email'),f.get('password'));await refresh();}catch(err){$('#login-error').textContent=err.message;b.disabled=false;}};document.querySelectorAll('[data-demo]').forEach(el=>el.onclick=async()=>{try{await api.demoLogin(el.dataset.demo);await refresh();}catch(err){$('#login-error').textContent=err.message;}});}
function renderHostedLogin(){
 setDossierViewer(null);
 $('#app').innerHTML=`<main class="login-page"><section class="login-splash"><a class="brand" href="/"><img class="brand-logo" src="/assets/brand/arios-logo-navy-gold-v2.webp" width="150" height="126" alt="لوگوی آریوس"><small class="brand-caption">فضای کار یکپارچهٔ آریوس</small></a><div><div class="hero-kicker">فضای کار اختصاصی تیم شما</div><h1>هر پروژه،<br>یک مسیر روشن</h1><p>پروژه‌ها، ویس‌های تیم و گزارش‌های کار؛ منظم و قابل پیگیری.</p></div><div class="login-splash-foot">ARIOS · OPERATIONS SYSTEM</div></section><section class="login-card"><div class="eyebrow">ARIOS WORKSPACE</div><h2>ورود به فضای کار آریوس</h2><p class="muted">با حساب ChatGPT مجاز خود وارد شوید. نقش و پروژه‌های شما در آریوس تعیین می‌شود.</p>${session?.message?`<p class="notice">${e(session.message)}</p>`:''}<a class="button primary full" href="/signin-with-chatgpt?return_to=%2F" target="_top">ورود با ChatGPT ${icon('arrow')}</a><p class="voice-login-note">برای دسترسی به پروژه‌ها، ایمیل حسابتان باید توسط مدیر آریوس به تیم اضافه شده باشد.</p></section></main>`;
}

async function refresh(){session=await api.session();setDossierViewer(session.user);if(!session.user){renderLogin();return;}state=await api.state();render();}
window.addEventListener('hashchange',()=>{if(state){render();window.scrollTo({top:0,behavior:'instant'});}});
refresh().catch(err=>{$('#app').innerHTML=`<main class="empty"><h1>دسترسی به فضای کار ممکن نشد</h1><p>${e(err.message)}</p><button class="button primary" id="reload-app">تلاش دوباره</button></main>`;$('#reload-app').onclick=()=>location.reload();});
